function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 - 60);
  ctx.lineTo(W/2 - 30, H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 - 60);
  ctx.lineTo(W/2 + 30, H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 20);
  ctx.lineTo(W/2 + 20, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 80);
  ctx.lineTo(W/2, H/2 - 100 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 40 + 10 * Math.sin(t), H/2);
  ctx.lineTo(W/2 - 60 + 10 * Math.sin(t), H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 40 - 10 * Math.sin(t), H/2);
  ctx.lineTo(W/2 + 60 - 10 * Math.sin(t), H/2 + 20);
  ctx.stroke();
  ctx.restore();
}
